/**
 * Derives src-tauri/assets/skill-name-sources.json — the bridge from the ids the
 * damage hook reports to the hashes the autogenerated lang files are keyed by.
 *
 * ui.json keys skill rows by ACTION ID; abilities.json keys them by ABILITY HASH.
 * Nothing at runtime connects the two, so this script generated that link once
 * from the English names then in ui.json, after which those names were deleted
 * and the artifact became the source of truth. Validating is therefore the
 * DEFAULT: the names a rebuild reads are the ones it already consumed, so a
 * plain re-derivation resolves almost nothing.
 *
 * `--rebuild` stays available for a game update that leaves new hand labels in
 * ui.json, or renames an entry the map points at. It layers what it resolves
 * OVER the committed artifact rather than replacing it, so it can only add or
 * correct entries — see buildSkillNameSources.
 *
 * `--from-game-data` is the automatic path: it reads the ability tags the game
 * itself ships in `system/player/data/pl####/pl####_action.msg` (the local
 * `icon-export/` dump — see src/assets/game-icons/README.md for the extraction
 * pipeline) and layers every edge nobody hand-labelled over the artifact. This
 * is how a patch-added ability (Gallanza's Flashpoint, action 1900) gets its
 * name without anyone playing the character and transcribing ids.
 *
 * Usage:
 *   node scripts/gen-skill-name-sources.mjs                  # validate, write nothing
 *   node scripts/gen-skill-name-sources.mjs --rebuild        # re-derive from ui.json labels
 *   node scripts/gen-skill-name-sources.mjs --from-game-data # derive from the action.msg dump
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { gameXxhash32 } from "./gbfr-hash.mjs";
import { msgDecode } from "./msg-decode.mjs";

/** Tier suffix on summon names. The ASCII form requires leading whitespace so a
 * name genuinely ending in "I" survives; the full-width form (zh-CN ships
 * "黑龙伊弗欧Ⅲ") carries no space. Mirrored in src/skillNameSources.ts — keep
 * both in step; the two test suites share fixtures to catch drift. */
const TIER_SUFFIX = /(?:\s+I{1,3}|[Ⅰ-Ⅲ])$/;

const SUMMON_CLASSES = "summon-classes";

export const normalizeName = (text) => String(text).replace(/\s+/g, " ").trim();

export const stripTierSuffix = (text) => normalizeName(normalizeName(text).replace(TIER_SUFFIX, ""));

/** Resolves a ui.json skill label to the ability hash of the same name.
 *
 * Every matchable name is ambiguous globally — the game ships a base ability and
 * a `_CG` cutscene twin under the same text — but unique inside its own
 * character, so scoping to `AB_<PLXXXX>_` is what makes this deterministic.
 * abilities.json holds no duplicate keys, so scoping plus the `_CG` preference
 * always leaves exactly one hash.
 */
export const pickAbilityHash = (characterBlock, label, abilities) => {
  const character = /^Pl(\d{4})$/.exec(characterBlock);
  if (character === null) return null;

  const wanted = normalizeName(label);
  const scope = new RegExp(`^AB_PL${character[1]}_\\d\\d(_CG)?$`);

  const candidates = Object.entries(abilities)
    .filter(([, entry]) => normalizeName(entry.text) === wanted && scope.test(entry.key))
    .sort(([aHash, a], [bHash, b]) => {
      const cg = Number(a.key.endsWith("_CG")) - Number(b.key.endsWith("_CG"));
      return cg !== 0 ? cg : aHash.localeCompare(bHash);
    });

  if (candidates.length === 0) return null;

  const [hash, entry] = candidates[0];
  return { ns: "abilities", hash, key: entry.key };
};

/** Candidates in a generated bundle whose tier-stripped text equals `wanted`. */
const summonCandidates = (bundle, wanted) =>
  Object.entries(bundle)
    .filter(([, entry]) => stripTierSuffix(entry.text) === wanted)
    .sort(byTierThenHash);

/** True when every candidate resolves to the same stripped text in every
 * language that ships the bundle. Duplicate keys are only interchangeable if
 * they stay interchangeable after translation. */
const candidatesAgree = (hashes, byLang) =>
  Object.values(byLang).every((bundle) => {
    const texts = new Set(hashes.map((hash) => (bundle[hash] ? stripTierSuffix(bundle[hash].text) : null)));
    return texts.size === 1 && !texts.has(null);
  });

const SUMMON_KEY = /^TXT_SMN_(So[0-9a-f]{4})(?:_\d+)?$/;

/** summons.json entries grouped by the body-class hash of their `So####` id,
 * best first: suffix-free text before tiered text, then smaller hash.
 *
 * A body class is `XXHash32Custom("So####")`, so this pairs a class with its
 * summon by IDENTITY. Name matching cannot: two different summons ship the same
 * display name, and the game reuses names for enemies too. */
const summonEntriesByClass = (summons) => {
  const byClass = new Map();

  for (const [hash, entry] of Object.entries(summons)) {
    const match = SUMMON_KEY.exec(entry.key);
    if (match === null) continue;

    const classHash = gameXxhash32(match[1]);
    if (!byClass.has(classHash)) byClass.set(classHash, []);
    byClass.get(classHash).push([hash, entry]);
  }

  for (const candidates of byClass.values()) candidates.sort(byTierThenHash);

  return byClass;
};

/** Suffix-free text first, then smaller hash — every tier of one summon strips to
 * the same display name, so which one wins only needs to be deterministic. */
const byTierThenHash = ([aHash, a], [bHash, b]) => {
  const tiered =
    Number(stripTierSuffix(a.text) !== normalizeName(a.text)) -
    Number(stripTierSuffix(b.text) !== normalizeName(b.text));
  return tiered !== 0 ? tiered : aHash.localeCompare(bHash);
};

/** Resolves a summon body class to a hash in a generated bundle.
 *
 * Identity first: hash every `So####` id in summons.json and look for the class.
 * Only when no id hashes to it — the Cat and Lilith bodies are not `So####`
 * summons — fall back to matching the ui.json label by name, against summons.json
 * then enemies.json. `via` records which path was taken so the two mechanisms
 * stay distinguishable in review.
 *
 * Returns null rather than guessing.
 */
export const pickSummonHash = (classHash, label, summons, enemies, summonsByLang) => {
  const byIdentity = summonEntriesByClass(summons).get(classHash);
  if (byIdentity !== undefined) {
    if (
      !candidatesAgree(
        byIdentity.map(([hash]) => hash),
        summonsByLang
      )
    ) {
      return null;
    }

    const [hash, entry] = byIdentity[0];
    return { ns: "summons", hash, key: entry.key, via: "id" };
  }

  const summonHits = summonCandidates(summons, stripTierSuffix(label));
  if (summonHits.length > 0) {
    if (
      !candidatesAgree(
        summonHits.map(([hash]) => hash),
        summonsByLang
      )
    ) {
      return null;
    }

    const [hash, entry] = summonHits[0];
    return { ns: "summons", hash, key: entry.key, via: "name" };
  }

  const enemyHit = Object.entries(enemies)
    .filter(([, entry]) => normalizeName(entry.text) === normalizeName(label))
    .sort(([a], [b]) => a.localeCompare(b))[0];

  if (enemyHit === undefined) return null;
  return { ns: "enemies", hash: enemyHit[0], key: enemyHit[1].key, via: "name" };
};

/** Walks every string leaf under ui.json's `skills` and resolves what it can,
 * layered over `existing` — whatever the committed artifact already holds.
 *
 * The merge is what makes a rebuild safe. Every name this derives from is
 * DELETED out of ui.json once mapped, so a re-derivation today resolves only the
 * leaves nobody has mapped yet; replacing the artifact with that would wipe the
 * map. A freshly resolved id still wins over the stored one, which is how a
 * rename gets corrected.
 *
 * Blocks are emitted sorted, and ids sorted numerically where possible, so a
 * re-run produces a byte-identical artifact and review diffs stay readable.
 */
export const buildSkillNameSources = (ui, generated, existing = {}) => {
  const sources = Object.fromEntries(Object.entries(existing).map(([block, entries]) => [block, { ...entries }]));
  const unmapped = [];
  let mapped = 0;

  for (const block of Object.keys(ui.skills ?? {}).sort()) {
    const entries = ui.skills[block];
    if (typeof entries !== "object" || entries === null) continue;

    const ids = sortIds(Object.keys(entries));

    for (const id of ids) {
      const label = entries[id];
      if (typeof label !== "string") continue;

      const source =
        block === SUMMON_CLASSES
          ? // The id IS the body-class hash for this block, which is what lets the
            // summon half resolve by identity instead of by display name.
            pickSummonHash(id, label, generated.summons, generated.enemies, generated.summonsByLang)
          : pickAbilityHash(block, label, generated.abilities);

      if (source === null) {
        unmapped.push({ block, id, label });
        continue;
      }

      sources[block] ??= {};
      sources[block][id] = source;
      mapped += 1;
    }
  }

  return { sources: sortSources(sources), report: { mapped, unmapped } };
};

/** The game's own action id -> ability edge, layered over `existing`.
 *
 * `rows` come from `system/player/data/pl####/pl####_action.msg`: each
 * ActionInfo row carries its action `id_` and, for base ability actions, an
 * `abilityTag_` (`AB_PL####_NN`) — the link ui.json hand labels used to
 * supply by hand. Merge rules, in order:
 *
 *   1. An entry already in the artifact stays. It is human-reviewed; when the
 *      tag points elsewhere that is a report line, never a silent overwrite.
 *   2. An action any language still hand-labels is skipped: labels are often
 *      MORE specific than the game's name ("Overdrive Surge (Arts I)" vs
 *      "Overdrive Surge"), and validateSources treats coexistence as an error.
 *   3. A tag naming ANOTHER character's ability is skipped and reported. Dev
 *      copy-paste junk has exactly that shape — Io's empowered Gravity Well
 *      rows carry Gran's Decimate, Djeeta's 1610-1613 carry it on rows her
 *      labels call Miserable Mist — and a name from outside the block's own
 *      key space cannot be told apart from it automatically. (utils.test.ts
 *      enforces the same scoping invariant over the committed artifact.)
 *   4. The tag resolves to the base key, else its _CG cutscene twin, else it
 *      is reported unresolved. What remains is added.
 */
export const buildGameDataSources = (rows, abilities, uiByLang, existing = {}) => {
  const hashOfKey = new Map(Object.entries(abilities).map(([hash, entry]) => [entry.key, hash]));
  const sources = Object.fromEntries(Object.entries(existing).map(([block, entries]) => [block, { ...entries }]));
  const report = { added: [], cross: [], disagreements: [], labelled: [], unresolved: [] };

  for (const { block, id, tag } of rows) {
    const have = sources[block]?.[id];
    if (have !== undefined) {
      if (have.key !== tag && have.key !== `${tag}_CG`) {
        report.disagreements.push({ block, id, have: have.key, tag });
      }
      continue;
    }

    if (Object.values(uiByLang).some((ui) => typeof ui.skills?.[block]?.[id] === "string")) {
      report.labelled.push({ block, id, tag });
      continue;
    }

    if (!tag.startsWith(`AB_${block.replace(/^Pl/, "PL")}_`)) {
      report.cross.push({ block, id, tag });
      continue;
    }

    const key = hashOfKey.has(tag) ? tag : `${tag}_CG`;
    if (!hashOfKey.has(key)) {
      report.unresolved.push({ block, id, tag });
      continue;
    }

    sources[block] ??= {};
    sources[block][id] = { ns: "abilities", hash: hashOfKey.get(key), key };
    report.added.push({ block, id, key });
  }

  return { sources: sortSources(sources), report };
};

/** Ids sorted by value when the whole block is numeric, lexically otherwise.
 *
 * The decision is per BLOCK, not per pair. Action ids are decimal, but summon
 * class ids are hex, where some parse as numbers ("69893920") and some do not
 * ("0254b5ee") — mixing the two comparisons in one pass is not a total order, so
 * sorting an already-sorted block permutes it and every rebuild churns the
 * artifact.
 */
const sortIds = (ids) =>
  ids.every((id) => /^\d+$/.test(id)) ? [...ids].sort((a, b) => Number(a) - Number(b)) : [...ids].sort();

/** The artifact's committed shape: blocks sorted, then ids. Applied after the
 * merge so a rebuild diffs against the file rather than reshuffling it. */
const sortSources = (sources) =>
  Object.fromEntries(
    Object.keys(sources)
      .sort()
      .map((block) => [
        block,
        Object.fromEntries(sortIds(Object.keys(sources[block])).map((id) => [id, sources[block][id]])),
      ])
  );

/** Validates a committed bridge map. The map is the source of truth once the
 * English names are deleted from ui.json, so re-runs check rather than rebuild.
 * Returns a list of human-readable errors; empty means healthy.
 */
export const validateSources = (sources, generated, uiByLang) => {
  const errors = [];
  const bundles = { abilities: generated.abilities, summons: generated.summons, enemies: generated.enemies };

  for (const [block, entries] of Object.entries(sources)) {
    for (const [id, source] of Object.entries(entries)) {
      const text = bundles[source.ns]?.[source.hash]?.text;
      if (!text) {
        errors.push(
          `${block}.${id} -> ${source.ns}:${source.hash} (${source.key}) no longer resolves; a game patch may have renamed it`
        );
      }

      for (const [lang, ui] of Object.entries(uiByLang)) {
        if (typeof ui.skills?.[block]?.[id] === "string") {
          errors.push(`${lang}/ui.json duplicates mapped entry skills.${block}.${id}; delete it or drop the mapping`);
        }
      }
    }
  }

  return errors;
};

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const LANG_DIR = path.join(ROOT, "src-tauri", "lang");
const ARTIFACT = path.join(ROOT, "src-tauri", "assets", "skill-name-sources.json");

const ALL_LANGS = ["en", "bp", "es", "fr", "ge", "it", "jp", "ko", "zh-CN", "zh-TW"];

const readLang = (lang, ns) => {
  const file = path.join(LANG_DIR, lang, `${ns}.json`);
  return existsSync(file) ? JSON.parse(readFileSync(file, "utf8")) : null;
};

const loadInputs = () => {
  const summonsByLang = {};
  const uiByLang = {};

  for (const lang of ALL_LANGS.filter((lang) => existsSync(path.join(LANG_DIR, lang)))) {
    const summons = readLang(lang, "summons");
    if (summons !== null) summonsByLang[lang] = summons;

    // Six languages ship no ui.json by design; that is not a failure.
    const ui = readLang(lang, "ui");
    if (ui !== null) uiByLang[lang] = ui;
    else console.warn(`[gen] ${lang}: no ui.json, skipping`);
  }

  return {
    uiByLang,
    generated: {
      abilities: readLang("en", "abilities"),
      summons: readLang("en", "summons"),
      enemies: readLang("en", "enemies"),
      summonsByLang,
    },
  };
};

/** Lists hand translations that disagree with the game's own text. Deleting the
 * ui.json entry adopts the game's spelling, so every line here is a judgement a
 * human should see rather than a silent overwrite. */
const reportDisagreements = (sources, uiByLang, generated) => {
  for (const [lang, ui] of Object.entries(uiByLang)) {
    if (lang === "en") continue;

    for (const [block, entries] of Object.entries(sources)) {
      for (const [id, source] of Object.entries(entries)) {
        const current = ui.skills?.[block]?.[id];
        if (typeof current !== "string") continue;

        const bundle = source.ns === "summons" ? generated.summonsByLang[lang] : readLang(lang, source.ns);
        const target = bundle?.[source.hash]?.text;
        if (target === undefined) continue;

        if (stripTierSuffix(target) !== normalizeName(current)) {
          console.log(
            `[gen] ${lang} skills.${block}.${id}: ${JSON.stringify(current)} -> game says ${JSON.stringify(stripTierSuffix(target))}`
          );
        }
      }
    }
  }
};

/** Every (block, action id, ability tag) edge in the local action.msg dump.
 * Base ability actions only — that is all the game tags; variant actions
 * (arts levels, follow-ups) stay the hand-label problem they always were. */
const readActionTagRows = () => {
  const playerDir = path.join(ROOT, "icon-export", "raw", "system", "player");
  const rows = [];

  for (let pl = 0; pl <= 99; pl++) {
    const id = `pl${String(pl).padStart(2, "0")}00`;
    // Archive paths are case-sensitive and split across data/ and Data/.
    const file = ["data", "Data"]
      .map((caseDir) => path.join(playerDir, caseDir, id, `${id}_action.msg`))
      .find(existsSync);
    if (file === undefined) continue;

    for (const [key, value] of msgDecode(readFileSync(file))) {
      if (key !== "ActionInfo") continue;
      const action = Object.fromEntries(value);
      if (/^AB_(?:PL|NP)\d{4}_\d{2}$/.test(action.abilityTag_ ?? "")) {
        rows.push({ block: `Pl${id.slice(2)}`, id: String(action.id_), tag: action.abilityTag_ });
      }
    }
  }

  return rows;
};

const main = () => {
  const { uiByLang, generated } = loadInputs();
  const existing = existsSync(ARTIFACT) ? JSON.parse(readFileSync(ARTIFACT, "utf8")) : {};

  if (process.argv.includes("--from-game-data")) {
    const rows = readActionTagRows();
    if (rows.length === 0) {
      console.error("[gen] no pl####_action.msg files under icon-export/raw/system/player/");
      console.error("[gen] run the extraction in src/assets/game-icons/README.md first");
      process.exit(1);
    }

    const { sources, report } = buildGameDataSources(rows, generated.abilities, uiByLang, existing);

    for (const { block, id, key } of report.added) {
      console.log(`[gen] + ${block}.${id} -> ${key}`);
    }
    for (const { block, id, tag } of report.cross) {
      console.warn(`[gen] ${block}.${id} tagged with another character's ${tag}; skipped — label it by hand`);
    }
    for (const { block, id, have, tag } of report.disagreements) {
      console.warn(`[gen] artifact ${block}.${id} holds ${have} but the game tags ${tag}; kept the artifact`);
    }
    for (const { block, id, tag } of report.unresolved) {
      console.warn(`[gen] ${block}.${id} tag ${tag} resolves to no abilities.json entry`);
    }
    console.log(
      `[gen] ${rows.length} tagged actions: ${report.added.length} added, ` +
        `${report.labelled.length} hand-labelled (labels win), ${report.cross.length} cross-character skip(s), ` +
        `${report.disagreements.length} disagreement(s), ${report.unresolved.length} unresolved`
    );

    const errors = validateSources(sources, generated, uiByLang);
    if (errors.length > 0) {
      console.error(`[gen] refusing to write: the merged map fails validation:`);
      for (const error of errors) console.error(`  - ${error}`);
      process.exit(1);
    }

    writeFileSync(ARTIFACT, `${JSON.stringify(sources, null, 2)}\n`, "utf8");
    console.log(`[gen] wrote ${path.relative(ROOT, ARTIFACT)}`);
    return;
  }

  // Validating is the default; `--check` is accepted so older invocations and
  // notes keep working.
  if (!process.argv.includes("--rebuild")) {
    const errors = validateSources(existing, generated, uiByLang);

    if (errors.length > 0) {
      console.error(`[gen] ${errors.length} problem(s):`);
      for (const error of errors) console.error(`  - ${error}`);
      process.exit(1);
    }

    console.log("[gen] bridge map is healthy");
    return;
  }

  const { sources, report } = buildSkillNameSources(uiByLang.en, generated, existing);

  writeFileSync(ARTIFACT, `${JSON.stringify(sources, null, 2)}\n`, "utf8");

  const kept = countEntries(existing);
  console.log(`[gen] wrote ${path.relative(ROOT, ARTIFACT)}: ${report.mapped} resolved over ${kept} already mapped`);
  console.log(`[gen] ${report.unmapped.length} leaves stay in ui.json (no game-data equivalent)`);
  reportDisagreements(sources, uiByLang, generated);
};

const countEntries = (sources) => Object.values(sources).reduce((n, entries) => n + Object.keys(entries).length, 0);

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
